export function formatError(error){
 if(!(error instanceof Error))throw new TypeError('error root');
 function describe(value,ancestors){
  if(!(value instanceof Error))return String(value);
  if(ancestors.includes(value))return '[Circular cause]';
  let text=value.name+': '+value.message;
  if(Object.hasOwn(value,'cause')&&value.cause!==undefined)text+='\nCaused by: '+describe(value.cause,[...ancestors,value]);
  return text;
 }
 return describe(error,[]);
}

